using QuantForge.Governance; using Xunit; namespace QuantForge.ArchitectureTests; public class LiveBrokerHeartbeatV22_70ArchitectureChecks { [Fact] public void HeartbeatBindsSessionAndBroker(){var t=DateTimeOffset.UtcNow;var h=new LiveBrokerHeartbeatV22_70("s",t.AddSeconds(-1),t,true,"b");Assert.True(LiveBrokerHeartbeatGateV22_70.IsHealthy(h,t,TimeSpan.FromSeconds(10),"s","b"));Assert.False(LiveBrokerHeartbeatGateV22_70.IsHealthy(h,t,TimeSpan.FromSeconds(10),"x","b"));} [Fact] public void StaleHeartbeatFails(){var t=DateTimeOffset.UtcNow;var h=new LiveBrokerHeartbeatV22_70("s",t.AddMinutes(-2),t.AddMinutes(-2),true,"b");Assert.False(LiveBrokerHeartbeatGateV22_70.IsHealthy(h,t,TimeSpan.FromSeconds(10),"s","b"));}}
